syntax:
To overload the function call operator in a class, define a member function named operator() with the desired parameters. For example:

class Screen {
public:
    // Const version for read-only access
    char operator()(int row, int col) const;

    // Non-const version for modification
    char& operator()(int row, int col);

    // Practical usage note: Always include bounds checking in the implementation to handle invalid indices gracefully, e.g., throw an exception or return a default value, promoting safer code.

code_example:
#include <iostream>
#include <string>

class Screen {
public:
    // Constructor for a screen with given height and width
    Screen(std::string contents, int h, int w) : contents(contents), height(h), width(w) {}

    // Overloaded function call operator for const access
    char operator()(int row, int col) const {
        if (row >= 0 && row < height && col >= 0 && col < width) {
            return contents[row * width + col];  // Assuming a 1D string representation
        } else {
            throw std::out_of_range("Screen access out of bounds");  // Bounds checking
        }
    }

    // Overloaded function call operator for non-const access
    char& operator()(int row, int col) {
        if (row >= 0 && row < height && col >= 0 && col < width) {
            return contents[row * width + col];
        } else {
            throw std::out_of_range("Screen access out of bounds");
        }
    }

private:
    std::string contents;  // Internal data storage
    int height;
    int width;
};

// Usage example
int main() {
    Screen myScreen(std::string(25, ' '), 5, 5);  // 5x5 screen filled with spaces
    myScreen(2, 3) = 'X';  // Modify using operator()
    std::cout << myScreen(2, 3) << std::endl;  // Access using operator()
    return 0;
}
